export const GMAIL_SCOPE='https://www.googleapis.com/auth/gmail.readonly';
export function decodeBase64Url(data){const base64=data.replace(/-/g,'+').replace(/_/g,'/');const raw=atob(base64);return new TextDecoder().decode(Uint8Array.from(raw,c=>c.charCodeAt(0)));}
export function plainEmail(payload){if(!payload)return '';if(payload.mimeType==='text/plain'&&payload.body?.data)return decodeBase64Url(payload.body.data);for(const part of payload.parts||[]){const text=plainEmail(part);if(text)return text;}return '';}
export function headerValue(message,name){return (message.payload?.headers||[]).find(h=>h.name.toLowerCase()===name.toLowerCase())?.value||'';}
export function selectedEmailText(message){const text=plainEmail(message.payload);return {text:['From: '+headerValue(message,'From'),'Subject: '+headerValue(message,'Subject'),'Date: '+headerValue(message,'Date'),'',text||message.snippet||'No plain-text content available.'].join('\n').slice(0,2000),previewOnly:!text};}
export class GmailReader{
 constructor(fetcher=fetch){this.fetcher=fetcher;this.accessToken='';this.expiresAt=0;}
 setToken(response){if(response.error||typeof response.access_token!=='string')throw Error('Google did not grant Gmail access.');this.accessToken=response.access_token;this.expiresAt=Date.now()+Math.min(Number(response.expires_in)||3600,3600)*1000;}
 clear(){this.accessToken='';this.expiresAt=0;}
 async get(path,params={},signal){if(!this.accessToken||Date.now()>=this.expiresAt){this.clear();throw Error('Gmail access expired. Connect again to continue.');}const url=new URL('https://gmail.googleapis.com/gmail/v1/users/me/'+path);Object.entries(params).forEach(([key,value])=>{for(const item of Array.isArray(value)?value:[value])url.searchParams.append(key,item);});const response=await this.fetcher(url.toString(),{headers:{Authorization:'Bearer '+this.accessToken},cache:'no-store',signal});if(response.status===401){this.clear();throw Error('Gmail access expired or was revoked. Connect again.');}if(!response.ok)throw Error(response.status===403?'Google has not allowed Gmail access for this account. The app may need verification or test-user approval.':'Gmail could not complete the request. Please try again.');return response.json();}
 async list(query=''){const result=await this.get('messages',{maxResults:'12',q:query.trim()||'in:inbox newer_than:30d',fields:'messages(id),nextPageToken'});const rows=[];for(const message of result.messages||[]){rows.push(await this.get('messages/'+encodeURIComponent(message.id),{format:'metadata',metadataHeaders:['From','Subject','Date'],fields:'id,snippet,sizeEstimate,payload(headers)'}));}return {rows,more:!!result.nextPageToken};}
 async read(id,sizeEstimate,signal){if(!/^[a-zA-Z0-9_-]{1,128}$/.test(id))throw Error('Invalid message selection.');if(Number(sizeEstimate)>262144)throw Error('This email is too large to import. Paste a short excerpt instead.');return this.get('messages/'+encodeURIComponent(id),{format:'full',fields:'id,snippet,payload(headers,mimeType,body(data),parts(mimeType,body(data),parts(mimeType,body(data),parts(mimeType,body(data)))))'},signal);}
}
export async function loadGoogleIdentity(){if(globalThis.google?.accounts?.oauth2)return;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=()=>reject(Error('Google sign-in could not load. Check your connection and try again.'));document.head.append(script);});}
